import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class ApiService {
  private readonly baseUrl = environment.apiUrl;

  constructor(private http: HttpClient) {}

  getDashboardData(): Observable<any> {
    return this.http.get(`${this.baseUrl}/api/dashboard`);
  }

  getWidgetData(widgetId: string): Observable<any> {
    return this.http.get(`${this.baseUrl}/api/dashboard/widgets/${widgetId}`);
  }

  exportReport(format: string): Observable<Blob> {
    return this.http.get(`${this.baseUrl}/api/dashboard/export`, {
      params: { format },
      responseType: 'blob'
    });
  }
}
